  function buildGyeyangAptTowersGeoJSON(){
    return {
      type: "FeatureCollection",
      features: GYEYANG_APT_TOWERS_RAW.map(function(item){
        var floors = item[0];
        var ring = item[1];
        var color = item[2] || null;
        return {
          type: "Feature",
          properties: { floors: floors, height: floors * 3, color: color },
          geometry: { type: "Polygon", coordinates: [ring] }
        };
      })
    };
  }

