  function buildRoadsGeoJSON(raw){
    return {
      type: "FeatureCollection",
      features: raw.map(function(item){
        return {
          type: "Feature",
          properties: { cls: item[0] },
          geometry: { type: "LineString", coordinates: item[1] }
        };
      })
    };
  }
  function buildRiversGeoJSON(raw){
    return {
      type: "FeatureCollection",
      features: raw.map(function(ring){
        return {
          type: "Feature",
          properties: {},
          geometry: { type: "Polygon", coordinates: [ring] }
        };
      })
    };
  }
  var currentViewKey = "incheon";
  var isTilted = true;

  var droneActive = false;
  var droneIndex = 0;
  var droneTimerId = null;
  var droneMarker = null;
  var DRONE_FLY_DURATION = 3200;
  var DRONE_DWELL = 2200;

  var autoRotateActive = false;
  var autoRotateRAF = null;
  var AUTO_ROTATE_SPEED = 0.045; // 프레임당 회전각(도) — 대략 초당 2~3도


    var map = new mapboxgl.Map({
      container: "map3d",
      style: "mapbox://styles/mapbox/outdoors-v12", // 등고선·음영기복(hillshade)이 기본 포함된 스타일
      center: VIEWS.incheon.center,
      zoom: VIEWS.incheon.zoom,
      pitch: VIEWS.incheon.pitch,
      bearing: VIEWS.incheon.bearing,
      antialias: true
    });
    map.addControl(new mapboxgl.NavigationControl({ visualizePitch: true }), "top-right");

    // ---- 마우스 휠(가운데) 버튼 드래그로 회전 (스케치업 오빗 방식) ----
    (function(){
      var canvas = map.getCanvasContainer();
      var dragging = false;
      var lastX = 0, lastY = 0;
      var ROTATE_SENSITIVITY = 0.28; // 좌우 이동량 -> 방위각(도)
      var PITCH_SENSITIVITY = 0.28;  // 상하 이동량 -> 기울기(도)

      canvas.addEventListener("mousedown", function(e){
        if (e.button !== 1) return; // 1 = 휠(가운데) 버튼
        e.preventDefault();
        dragging = true;
        lastX = e.clientX;
        lastY = e.clientY;
        canvas.style.cursor = "grabbing";
        if (droneActive) stopDroneTour();
        if (autoRotateActive) setAutoRotate(false);
      });

      window.addEventListener("mousemove", function(e){
        if (!dragging) return;
        var dx = e.clientX - lastX;
        var dy = e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;
        if (e.shiftKey) {
          // Shift + 휠버튼 드래그: 회전 대신 화면 이동(좌클릭 드래그와 동일한 느낌)
          map.panBy([-dx, -dy], { duration: 0 });
        } else {
          // 휠버튼만 드래그: 회전 (좌우는 기존 대비 방향 반전, 상하는 한 번 더 반전)
          var nextBearing = map.getBearing() + dx * ROTATE_SENSITIVITY;
          var nextPitch = Math.max(0, Math.min(85, map.getPitch() - dy * PITCH_SENSITIVITY));
          map.jumpTo({ bearing: nextBearing, pitch: nextPitch });
        }
      });

      function endDrag(e){
        if (!dragging) return;
        if (e && e.type === "mouseup" && e.button !== 1) return;
        dragging = false;
        canvas.style.cursor = "";
      }
      window.addEventListener("mouseup", endDrag);
      window.addEventListener("blur", function(){ dragging = false; canvas.style.cursor = ""; });

      // 가운데 버튼을 눌렀다 뗄 때 브라우저 기본 동작(자동 스크롤 아이콘, 새 탭 열기 등) 막기
      canvas.addEventListener("auxclick", function(e){
        if (e.button === 1) e.preventDefault();
      });
    })();

    // 지도 로드 후: (1) 실제 표고 데이터로 지형을 입체로 세우고,
    // (2) 하늘(대기) 레이어를 추가해서 원근감·분위기를 살리고,
    // (3) 도면/렌더링 같은 분위기가 나도록 등고선·음영기복만 강조하고 나머지는 차분하게 누른다.
    map.on("style.load", function(){
      // 1) 3D 지형 (Mapbox 제공 실제 표고 데이터)
      if (!map.getSource("mapbox-dem")) {
        map.addSource("mapbox-dem", {
          type: "raster-dem",
          url: "mapbox://mapbox.mapbox-terrain-dem-v1",
          tileSize: 512,
          maxzoom: 14
        });
      }
      map.setTerrain({ source: "mapbox-dem", exaggeration: DEFAULT_EXAG });

      // 2) 하늘 레이어 (대기 원근감)
      if (!map.getLayer("sky")) {
        map.addLayer({
          id: "sky",
          type: "sky",
          paint: {
            "sky-type": "atmosphere",
            "sky-atmosphere-sun": [0.0, 75.0],
            "sky-atmosphere-sun-intensity": 8,
            "sky-atmosphere-color": "#dfe6ee"
          }
        });
      }

      // 3) 도면풍 색감 정리
      var layers = map.getStyle().layers || [];
      var labelLayerId = null;
      layers.forEach(function(layer){
        var id = layer.id.toLowerCase();
        try {
          if (id.indexOf("contour") !== -1 && layer.type === "line") {
            map.setPaintProperty(layer.id, "line-color", "#6b5a3f");
            map.setPaintProperty(layer.id, "line-opacity", 0.55);
          } else if (id.indexOf("hillshade") !== -1) {
            map.setPaintProperty(layer.id, "hillshade-exaggeration", 0.55);
          } else if (layer.type === "symbol" && (id.indexOf("poi") !== -1 || id.indexOf("transit") !== -1)) {
            map.setLayoutProperty(layer.id, "visibility", "none"); // 자잘한 아이콘/라벨 정리
          } else if (layer.type === "fill" && id.indexOf("land") !== -1) {
            map.setPaintProperty(layer.id, "fill-color", "#f5f1e9");
          } else if (layer.type === "line" && (id.indexOf("motorway") !== -1 || id.indexOf("trunk") !== -1)) {
            // 고속도로·간선도로는 눈에 띄게 굵고 진한 색으로 강조
            map.setPaintProperty(layer.id, "line-color", "#c0521f");
          } else if (layer.type === "line" && id.indexOf("road") !== -1) {
            map.setPaintProperty(layer.id, "line-color", "#c9beac");
          } else if (layer.type === "fill" && (id.indexOf("water") !== -1) && id.indexOf("waterway") === -1) {
            // 하천·저수지 등 수면부는 더 진하고 채도 있는 파란색으로(터파여 보이는 느낌을 색으로 흉내)
            map.setPaintProperty(layer.id, "fill-color", "#5f89ad");
          } else if (layer.type === "line" && id.indexOf("waterway") !== -1) {
            map.setPaintProperty(layer.id, "line-color", "#5f89ad");
          }
        } catch (e) { /* 레이어별로 없는 속성이면 조용히 무시 */ }
        // 건물 3D 레이어를 라벨(글자) 레이어 바로 아래에 끼워 넣기 위해, 첫 symbol 레이어 id를 기억해둔다
        if (!labelLayerId && layer.type === "symbol" && layer.layout && layer.layout["text-field"]) {
          labelLayerId = layer.id;
        }
      });

      // 3-1) 고가/교량 도로는 밝고 굵게 띄워서 "떠 있는" 느낌을 주고, 지하 구간(터널)은 점선으로 낮춰서 표현
      //      — 브이월드 같은 별도 API 없이, 이미 불러온 Mapbox 벡터 타일(도로 데이터의 structure 필드)만으로 가능합니다.
      try {
        if (!map.getLayer("road-bridge-highlight")) {
          map.addLayer({
            id: "road-bridge-highlight",
            source: "composite",
            "source-layer": "road",
            type: "line",
            filter: ["==", ["get", "structure"], "bridge"],
            paint: {
              "line-color": "#fff6e8",
              "line-width": ["interpolate", ["linear"], ["zoom"], 12, 1.5, 17, 6],
              "line-opacity": 0.9,
              "line-gap-width": 0
            }
          }, labelLayerId || undefined);
        }
        if (!map.getLayer("road-tunnel-dim")) {
          map.addLayer({
            id: "road-tunnel-dim",
            source: "composite",
            "source-layer": "road",
            type: "line",
            filter: ["==", ["get", "structure"], "tunnel"],
            paint: {
              "line-color": "#8a8175",
              "line-width": ["interpolate", ["linear"], ["zoom"], 12, 1, 17, 4],
              "line-opacity": 0.5,
              "line-dasharray": [2, 1.5]
            }
          }, labelLayerId || undefined);
        }
      } catch (e) { /* road source-layer가 다른 이름을 쓰는 스타일이면 조용히 무시 */ }

      // 3-4) 16차(2026-09-25): 10번 요청 — 실제 하천·도로 배경. 건물(3D 매스)보다 먼저 깔아서
      //      항상 건물들이 그 위(도로/하천은 바닥, 건물은 그 위로 솟아오르는 형태)에 보이도록 한다.
      if (!map.getSource("incheon-rivers")) {
        map.addSource("incheon-rivers", { type: "geojson", data: buildRiversGeoJSON(INCHEON_RIVERS_RAW) });
      }
      if (!map.getLayer("incheon-rivers")) {
        map.addLayer({
          id: "incheon-rivers",
          source: "incheon-rivers",
          type: "fill",
          paint: { "fill-color": "#5f89ad", "fill-opacity": 0.85 }
        }, labelLayerId || undefined);
      }
      if (!map.getSource("busan-rivers")) {
        map.addSource("busan-rivers", { type: "geojson", data: buildRiversGeoJSON(BUSAN_RIVERS_RAW) });
      }
      if (!map.getLayer("busan-rivers")) {
        map.addLayer({
          id: "busan-rivers",
          source: "busan-rivers",
          type: "fill",
          paint: { "fill-color": "#5f89ad", "fill-opacity": 0.85 }
        }, labelLayerId || undefined);
      }

      if (!map.getSource("incheon-roads")) {
        map.addSource("incheon-roads", { type: "geojson", data: buildRoadsGeoJSON(INCHEON_ROADS_RAW) });
      }
      if (!map.getLayer("incheon-roads")) {
        map.addLayer({
          id: "incheon-roads",
          source: "incheon-roads",
          type: "line",
          layout: { "line-join": "round", "line-cap": "round" },
          paint: {
            "line-color": ["match", ["get", "cls"], 0, "#c0521f", 1, "#d69a4e", "#c9beac"],
            "line-width": ["interpolate", ["linear"], ["zoom"], 10, ["match", ["get", "cls"], 0, 1.5, 1, 1, 0.6], 16, ["match", ["get", "cls"], 0, 6, 1, 4, 2.5]],
            "line-opacity": 0.9
          }
        }, labelLayerId || undefined);
      }
      if (!map.getSource("busan-roads")) {
        map.addSource("busan-roads", { type: "geojson", data: buildRoadsGeoJSON(BUSAN_ROADS_RAW) });
      }
      if (!map.getLayer("busan-roads")) {
        map.addLayer({
          id: "busan-roads",
          source: "busan-roads",
          type: "line",
          layout: { "line-join": "round", "line-cap": "round" },
          paint: {
            "line-color": ["match", ["get", "cls"], 0, "#c0521f", 1, "#d69a4e", "#c9beac"],
            "line-width": ["interpolate", ["linear"], ["zoom"], 10, ["match", ["get", "cls"], 0, 1.5, 1, 1, 0.6], 16, ["match", ["get", "cls"], 0, 6, 1, 4, 2.5]],
            "line-opacity": 0.9
          }
        }, labelLayerId || undefined);
      }

      // 4) 3D 건물 (Mapbox 기본 벡터 타일의 건물 높이 데이터 사용)
      // 2026-09-24 밤(5차): 세영님 요청으로 이 레이어 자체를 꺼뒀었음(visibility: none).
      // 2026-09-24 밤(6차 후속): 세영님이 "빌라·다세대·단독주택이 지도에 빠져있다"고 지적하심 —
      // 원인은 우리가 브이월드로 조사해온 건 전부 "8층 이상 아파트"만 걸러서 가져온 것이었고,
      // 저층 주택까지 브이월드로 전부 새로 받아오려니 한 구역(1km 남짓)에만 1,000개가 넘는
      // 건물이 있어서(페이지네이션 확인 결과 실제 1,124개) 계양구 전체로는 수만 개 단위 —
      // 정적 배열 방식으로는 파일 용량·지도 성능 모두 감당이 안 되는 규모로 확인됨.
      // 그래서 대신, 다시 켜되 "8층(약 24m) 미만 건물만" 보이도록 필터를 걸어 씀 — 맵박스
      // 자체 벡터타일은 이런 대량의 저층 건물을 효율적으로 처리하도록 만들어진 시스템이라
      // 우리가 일일이 받아오지 않아도 됨. 우리가 가진 실측 데이터(wide-area-buildings 등)는
      // 전부 8층 이상만 있으므로, 이 필터 덕분에 서로 겹칠 일도 없음.
      // 2026-09-24 밤(7차 후속): 세영님이 "줌아웃하면 이 저층 건물들이 또 사라진다"고 지적하심 —
      // 확인해보니 맵박스 공식 문서 기준 이 건물 데이터 자체가 "대형 건물은 줌 13부터, 전체 건물은
      // 줌 16부터"만 제공되는 타일이라(맵박스 쪽 데이터 자체의 태생적 한계), minzoom을 0으로 낮춰도
      // 도시 전체를 내려다보는 수준까지 줌아웃하면 어차피 타일 자체에 건물 데이터가 없어서 안 보이는
      // 건 마찬가지임. 다만 기존 14보다 타일이 실제로 채워지기 시작하는 13으로 한 단계 낮춰서, 어느
      // 정도 확대했을 때는 조금이라도 더 일찍 보이도록 조정함.
      if (!map.getLayer("3d-buildings")) {
        map.addLayer({
          id: "3d-buildings",
          source: "composite",
          "source-layer": "building",
          type: "fill-extrusion",
          minzoom: 13,
          filter: ["<", ["coalesce", ["get", "height"], 8], 24],
          paint: {
            "fill-extrusion-color": "#cfc6b8",
            "fill-extrusion-height": ["coalesce", ["get", "height"], 8],
            "fill-extrusion-base": ["coalesce", ["get", "min_height"], 0],
            "fill-extrusion-base-alignment": "terrain",
            "fill-extrusion-height-alignment": "flat",
            "fill-extrusion-opacity": 0.85
          }
        }, labelLayerId || undefined);
      }

      // 3-2) 넓은 범위(BOX)의 실제 건물들 — "배경을 채워주는" 용도. 우리가 특별히 조사한 6개
      //      단지보다 먼저(코드상 먼저 addLayer) 깔아서, 나중에 추가되는 조사 단지 색이
      //      항상 그 위에 그려지도록 한다 — 겹치는 자리에서도 "우리가 조사한 곳"이 우선 보인다.
      // 2026-09-24: 줌아웃 시 임의로 부풀리던 -far 레이어(높이 배율 + 최소 크기 확대)를 완전히
      // 제거하고, 실제 크기·실제 높이 그대로만 그린다(맵박스 기본 3d-buildings와 동일한 방식).
      if (!map.getSource("wide-area-buildings")) {
        map.addSource("wide-area-buildings", {
          type: "geojson",
          data: buildTowersGeoJSON(WIDE_AREA_BUILDINGS_RAW)
        });
      }
      if (!map.getLayer("wide-area-buildings")) {
        map.addLayer({
          id: "wide-area-buildings",
          source: "wide-area-buildings",
          type: "fill-extrusion",
          minzoom: 0,
          paint: {
            "fill-extrusion-color": ["coalesce", ["get", "color"], WIDE_AREA_COLOR],
            "fill-extrusion-height": ["coalesce", ["get", "height"], 8],
            "fill-extrusion-base": 0,
            "fill-extrusion-base-alignment": "terrain",
            "fill-extrusion-height-alignment": "flat",
            "fill-extrusion-opacity": 0.9
          }
        }, labelLayerId || undefined);
      }

      // 3-3) 15차 후속(2026-09-25): 부산에코델타시티 우리 현장 반경 10km 실제 건물 배경 채우기.
      //      인천의 wide-area-buildings와 완전히 같은 방식 — BUSAN_WIDE_AREA_BUILDINGS_RAW 참고.
      if (!map.getSource("busan-wide-area-buildings")) {
        map.addSource("busan-wide-area-buildings", {
          type: "geojson",
          data: buildTowersGeoJSON(BUSAN_WIDE_AREA_BUILDINGS_RAW)
        });
      }
      if (!map.getLayer("busan-wide-area-buildings")) {
        map.addLayer({
          id: "busan-wide-area-buildings",
          source: "busan-wide-area-buildings",
          type: "fill-extrusion",
          minzoom: 0,
          paint: {
            "fill-extrusion-color": ["coalesce", ["get", "color"], WIDE_AREA_COLOR],
            "fill-extrusion-height": ["coalesce", ["get", "height"], 8],
            "fill-extrusion-base": 0,
            "fill-extrusion-base-alignment": "terrain",
            "fill-extrusion-height-alignment": "flat",
            "fill-extrusion-opacity": 0.9
          }
        }, labelLayerId || undefined);
      }

      // 4-1) 인천계양 A21 인근 실제 아파트 건물(국토부 도로명주소 건물, 지상 8층 이상) 레이어 추가
      //      2026-09-24: -far 부풀리기 제거, 실제 크기·실제 높이 그대로만 그린다.
      if (!map.getSource("gyeyang-apt-towers")) {
        map.addSource("gyeyang-apt-towers", {
          type: "geojson",
          data: buildGyeyangAptTowersGeoJSON()
        });
      }
      if (!map.getLayer("gyeyang-apt-towers")) {
        map.addLayer({
          id: "gyeyang-apt-towers",
          source: "gyeyang-apt-towers",
          type: "fill-extrusion",
          minzoom: 0,
          paint: {
            "fill-extrusion-color": ["coalesce", ["get", "color"], REAL_APT_COLOR],
            "fill-extrusion-height": ["coalesce", ["get", "height"], 8],
            "fill-extrusion-base": 0,
            "fill-extrusion-base-alignment": "terrain",
            "fill-extrusion-height-alignment": "flat",
            "fill-extrusion-opacity": 1
          }
        }, labelLayerId || undefined);
      }

      // 4-1-b) 드론비행 6개 지점 중 나머지 4곳(작전역/힐스테이트자이계양, 효성해링턴플레이스,
      //        박촌역/풍림아이원, 임학역/코아루센트럴파크)의 실제 아파트 건물 레이어.
      if (!map.getSource("other-apt-towers")) {
        map.addSource("other-apt-towers", {
          type: "geojson",
          data: buildTowersGeoJSON(OTHER_APT_TOWERS_RAW)
        });
      }
      if (!map.getLayer("other-apt-towers")) {
        map.addLayer({
          id: "other-apt-towers",
          source: "other-apt-towers",
          type: "fill-extrusion",
          minzoom: 0,
          paint: {
            "fill-extrusion-color": ["coalesce", ["get", "color"], REAL_APT_COLOR],
            "fill-extrusion-height": ["coalesce", ["get", "height"], 8],
            "fill-extrusion-base": 0,
            "fill-extrusion-base-alignment": "terrain",
            "fill-extrusion-height-alignment": "flat",
            "fill-extrusion-opacity": 1
          }
        }, labelLayerId || undefined);
      }

      // 4-1-c) 계양 롯데캐슬 파크시티 — 아직 미착공이라 실제 데이터가 없는 "근사 매스".
      //        다른 실제 건물과 구분되도록 파란빛 회색 + 더 투명하게 표시하고, 클릭 시 안내 팝업을 띄운다.
      if (!map.getSource("lottecastle-approx")) {
        map.addSource("lottecastle-approx", {
          type: "geojson",
          data: buildTowersGeoJSON(LOTTE_CASTLE_APPROX_RAW)
        });
      }
      if (!map.getLayer("lottecastle-approx")) {
        map.addLayer({
          id: "lottecastle-approx",
          source: "lottecastle-approx",
          type: "fill-extrusion",
          minzoom: 0,
          paint: {
            "fill-extrusion-color": "#cfc6b8",
            "fill-extrusion-height": ["coalesce", ["get", "height"], 8],
            "fill-extrusion-base": 0,
            "fill-extrusion-base-alignment": "terrain",
            "fill-extrusion-height-alignment": "flat",
            "fill-extrusion-opacity": 0.55
          }
        }, labelLayerId || undefined);
      }
      if (!map.__lotteCastlePopupBound) {
        map.__lotteCastlePopupBound = true;
        ["lottecastle-approx"].forEach(function(lyr){
          map.on("click", lyr, function(){
            new mapboxgl.Popup({ closeOnClick: true })
              .setLngLat([126.70404, 37.53462])
              .setHTML("<div style='font-size:13px;line-height:1.5;'><b>계양 롯데캐슬 파크시티 (1단지)</b><br>미착공(완공예정 2027.11) — 조사한 설계 스펙(20개동, 지상 25~26층, 1,964세대) 기반 근사 매스이며 실제 동 배치도가 아닙니다.</div>")
              .addTo(map);
          });
          map.on("mouseenter", lyr, function(){ map.getCanvas().style.cursor = "pointer"; });
          map.on("mouseleave", lyr, function(){ map.getCanvas().style.cursor = ""; });
        });
      }

      // 4-1-d) 2026-09-24: 인천 17개+부산 24개 "비교단지" + 경쟁 분양현장 13개(총 53개) 근사 매스.
      //        실제 건물 외곽선이 아니라 브이월드 지오코더 좌표 기준 세대수 비례 박스(롯데캐슬과 같은 방식).
      //        12차(2026-09-24): 마커 유무로 매스 단위 구분이 불가해 테라코타 강조는 걷어내고 REAL_APT_COLOR로 통일.
      if (!map.getSource("comparison-complex-towers")) {
        map.addSource("comparison-complex-towers", {
          type: "geojson",
          data: buildTowersGeoJSON(COMPARISON_TOWERS_RAW)
        });
      }
      if (!map.getLayer("comparison-complex-towers")) {
        map.addLayer({
          id: "comparison-complex-towers",
          source: "comparison-complex-towers",
          type: "fill-extrusion",
          minzoom: 0,
          paint: {
            // 12차(2026-09-24): 마커 유무를 매스 단위로 구분할 수 없어 테라코타 강조를 걷어내고 일반 건물색으로 통일
            "fill-extrusion-color": REAL_APT_COLOR,
            "fill-extrusion-height": ["coalesce", ["get", "height"], 8],
            "fill-extrusion-base": 0,
            "fill-extrusion-base-alignment": "terrain",
            "fill-extrusion-height-alignment": "flat",
            "fill-extrusion-opacity": 1
          }
        }, labelLayerId || undefined);
      }

      // 4-2) (구) 위 사각 범위들 안쪽 맵박스 기본 건물을 지오메트리 기준(within)으로 꺼주던 로직.
      // 2026-09-24 밤(6차 후속): "3d-buildings"를 다시 켜면서, 겹침 방지 방식을 지오메트리 마스킹에서
      // 위쪽 필터(8층/24m 미만만 표시)로 바꿨기 때문에 이 함수는 더 이상 필요 없어져서 제거함 —
      // 우리 실측 데이터(wide-area-buildings 등)는 전부 8층 이상이라 애초에 겹칠 일이 없음.
    });

    // 위치 버튼
    document.querySelectorAll(".view-btn").forEach(function(btn){
      btn.addEventListener("click", function(){
        document.querySelectorAll(".view-btn").forEach(function(b){ b.classList.remove("active"); });
        btn.classList.add("active");
        currentViewKey = btn.getAttribute("data-view");
        var v = VIEWS[currentViewKey];
        map.flyTo({
          center: v.center,
          zoom: v.zoom,
          pitch: isTilted ? v.pitch : 0,
          bearing: isTilted ? v.bearing : 0,
          essential: true
        });
      });
    });

    // 평면/입체 토글
    var flatBtn = document.getElementById("m3dFlatBtn");
    var tiltBtn = document.getElementById("m3dTiltBtn");
    function setTilted(tilted){
      isTilted = tilted;
      flatBtn.classList.toggle("active", !tilted);
      tiltBtn.classList.toggle("active", tilted);
      var v = VIEWS[currentViewKey];
      map.easeTo({
        pitch: tilted ? v.pitch : 0,
        bearing: tilted ? v.bearing : 0,
        duration: 800
      });
    }
    flatBtn.addEventListener("click", function(){ setTilted(false); });
    tiltBtn.addEventListener("click", function(){ setTilted(true); });

    // 지형 강조 정도
    document.querySelectorAll(".exag-btn").forEach(function(btn){
      btn.addEventListener("click", function(){
        document.querySelectorAll(".exag-btn").forEach(function(b){ b.classList.remove("active"); });
        btn.classList.add("active");
        var exag = parseFloat(btn.getAttribute("data-exag"));
        map.setTerrain({ source: "mapbox-dem", exaggeration: exag });
      });
    });

    // 회전 버튼 (마우스 오른쪽 드래그가 불편한 경우를 위한 대안)
    document.getElementById("m3dRotateLeftBtn").addEventListener("click", function(){
      map.easeTo({ bearing: map.getBearing() - 45, duration: 400 });
    });
    document.getElementById("m3dRotateRightBtn").addEventListener("click", function(){
      map.easeTo({ bearing: map.getBearing() + 45, duration: 400 });
    });
    document.getElementById("m3dNorthBtn").addEventListener("click", function(){
      map.easeTo({ bearing: 0, duration: 400 });
    });

    // ---- 자동 회전 (제자리에서 계속 천천히 도는 연출) ----
    var autoRotateBtn = document.getElementById("m3dAutoRotateBtn");
    function autoRotateStep(){
      if (!autoRotateActive) return;
      map.setBearing(map.getBearing() + AUTO_ROTATE_SPEED);
      autoRotateRAF = requestAnimationFrame(autoRotateStep);
    }
    function setAutoRotate(on){
      autoRotateActive = on;
      autoRotateBtn.classList.toggle("active", on);
      autoRotateBtn.textContent = on ? "⏹ 자동 회전 중지" : "자동 회전";
      if (on) {
        if (droneActive) stopDroneTour();
        autoRotateRAF = requestAnimationFrame(autoRotateStep);
      } else if (autoRotateRAF) {
        cancelAnimationFrame(autoRotateRAF);
        autoRotateRAF = null;
      }
    }
    autoRotateBtn.addEventListener("click", function(){ setAutoRotate(!autoRotateActive); });

    // ---- 드론 비행 (예시 지점을 자동으로 순회하며 카메라가 날아다니는 연출) ----
    var droneBtn = document.getElementById("m3dDroneBtn");
    var droneOverlay = document.getElementById("m3dDroneOverlay");
    var droneOverlayText = document.getElementById("m3dDroneOverlayText");
    var droneOverlayDots = document.getElementById("m3dDroneOverlayDots");

    function createDroneMarkerEl(){
      var el = document.createElement("div");
      el.className = "m3d-drone-marker";
      return el;
    }

    function updateDroneOverlay(list, idx){
      var hotspot = list[idx];
      droneOverlayText.textContent = "드론 비행 · " + (idx + 1) + "/" + list.length + " · " + hotspot.name;
      droneOverlayDots.innerHTML = "";
      list.forEach(function(_, i){
        var dot = document.createElement("span");
        dot.className = "m3d-drone-dot" + (i === idx ? " active" : "");
        droneOverlayDots.appendChild(dot);
      });
      droneOverlay.classList.add("visible");
    }

    function goToHotspot(list, idx){
      var h = list[idx];
      if (!droneMarker) {
        droneMarker = new mapboxgl.Marker({ element: createDroneMarkerEl() });
      }
      droneMarker.setLngLat(h.center).addTo(map);
      updateDroneOverlay(list, idx);
      map.flyTo({
        center: h.center,
        zoom: h.zoom,
        pitch: h.pitch,
        bearing: h.bearing,
        duration: DRONE_FLY_DURATION,
        essential: true
      });
    }

    function droneTick(){
      if (!droneActive) return;
      var list = HOTSPOTS[currentViewKey] || HOTSPOTS.incheon;
      goToHotspot(list, droneIndex);
      droneTimerId = setTimeout(function(){
        if (!droneActive) return;
        droneIndex = (droneIndex + 1) % list.length;
        droneTick();
      }, DRONE_FLY_DURATION + DRONE_DWELL);
    }

    function startDroneTour(){
      droneActive = true;
      droneIndex = 0;
      droneBtn.classList.add("active");
      droneBtn.textContent = "⏹ 드론 비행 중지";
      if (autoRotateActive) setAutoRotate(false);
      isTilted = true;
      tiltBtn.classList.add("active");
      flatBtn.classList.remove("active");
      droneTick();
    }

    function stopDroneTour(){
      droneActive = false;
      if (droneTimerId) { clearTimeout(droneTimerId); droneTimerId = null; }
      droneBtn.classList.remove("active");
      droneBtn.textContent = "▶ 드론 비행 시작";
      droneOverlay.classList.remove("visible");
      if (droneMarker) { droneMarker.remove(); droneMarker = null; }
    }

    droneBtn.addEventListener("click", function(){
      if (droneActive) { stopDroneTour(); } else { startDroneTour(); }
    });

    // 사용자가 직접 지도를 드래그하거나 다른 위치/시점 버튼을 누르면 자동 연출은 멈춘다
    map.on("dragstart", function(){
      if (droneActive) stopDroneTour();
      if (autoRotateActive) setAutoRotate(false);
    });
    document.querySelectorAll(".view-btn").forEach(function(btn){
      btn.addEventListener("click", function(){
        if (droneActive) stopDroneTour();
        if (autoRotateActive) setAutoRotate(false);
      });
    });
    flatBtn.addEventListener("click", function(){
      if (droneActive) stopDroneTour();
    });

